51	    /** 处理液位上送。 */
52	    public LevelIngestResult ingest(LevelIngestRequest request) {
53	        PumpStation station = catalogRepository.findStation(request.stationCode())
54	                .orElseThrow(() -> ApiException.unprocessable("STATION_NOT_FOUND")
55	                        .raise("泵站不存在: " + request.stationCode()));
56	        LocalDateTime receivedAt = timeProvider.now();
57	
