81	                                                   LevelIngestRequest request,
82	                                                   LocalDateTime receivedAt) {
83	        // 站点＋时刻去重：命中则原样返回，不产生任何新副作用
84	        Long existingId = levelRepository.findIdByStationAndTime(
85	                station.code(), request.readingTime());
86	        if (existingId != null) {
87	            return new LevelIngestResult(existingId, station.code(), request.readingTime(),
88	                    false, true, false, null, null, null, null);
89	        }
90	
91	        // 失联判定以本次数据之前的末次液位时刻为基准，须在插入本次数据前取
92	        LocalDateTime lastReading = levelRepository.latestReadingTimeBefore(
93	                station.code(), event.id(), request.readingTime());
94	
95	        Long readingId = levelRepository.insert(station.code(), event.id(),
96	                request.readingTime(), request.level(), receivedAt);
97	        if (readingId == null) {
98	            // 并发下站点＋时刻被抢占，按去重返回首次ID
99	            Long concurrentId = levelRepository.findIdByStationAndTime(
100	                    station.code(), request.readingTime());
101	            return new LevelIngestResult(concurrentId, station.code(), request.readingTime(),
102	                    false, true, false, null, null, null, null);
