120	            reason = "SAFE_LOW";
121	        } else if (level.compareTo(station.targetLevel()) <= 0) {
122	            reason = "TARGET_REACHED";
123	        } else {
124	            return AutoStop.NONE;
125	        }
126	        Long taskId = pumpCommandService.autoStop(station, event, request.readingTime(), reason);
127	        return taskId == null ? AutoStop.NONE : new AutoStop(taskId, reason);
128	    }
