1	package com.example.starter.pump.business;
2	
3	import com.example.starter.pump.error.ApiException;
4	import com.example.starter.pump.service.PumpdownFacade;
5	import com.example.starter.pump.testsupport.AbstractIntegrationTest;
6	import com.example.starter.pump.web.dto.PumpCommandRequest;
7	import com.example.starter.pump.web.dto.WarningRequest;
8	import org.junit.jupiter.api.Test;
9	import org.springframework.beans.factory.annotation.Autowired;
10	
11	import java.time.LocalDateTime;
12	import java.util.concurrent.CountDownLatch;
13	import java.util.concurrent.ExecutorService;
14	import java.util.concurrent.Executors;
15	import java.util.concurrent.Future;
16	import java.util.concurrent.TimeUnit;
17	import java.util.concurrent.atomic.AtomicInteger;
18	
19	import static org.assertj.core.api.Assertions.assertThat;
20	
21	/**
22	 * 并发边界（真实多线程 + H2 唯一约束）：同一泵站同时刻并发启停指令唯一受理；
23	 * 同一分区同时刻不同站归入同一套联动序列。
24	 */
25	class PumpConcurrencyTest extends AbstractIntegrationTest {
26	
27	    private static final LocalDateTime T0 = LocalDateTime.of(2026, 9, 26, 8, 0);
28	
29	    @Autowired
30	    private PumpdownFacade facade;
31	
32	    @Test
33	    void sameStationSameTime_concurrentCommands_onlyOneAccepted() throws Exception {
34	        Long id = facade.handleWarning(new WarningRequest("w-c", "ZN", "ORANGE", T0)).pumpdownId();
35	
36	        int threads = 8;
37	        ExecutorService pool = Executors.newFixedThreadPool(threads);
38	        CountDownLatch ready = new CountDownLatch(threads);
39	        CountDownLatch start = new CountDownLatch(1);
40	        AtomicInteger accepted = new AtomicInteger();
41	        AtomicInteger conflict = new AtomicInteger();
42	        Future<?>[] futures = new Future[threads];
43	
44	        try {
45	            for (int i = 0; i < threads; i++) {
46	                final int idx = i;
47	                futures[i] = pool.submit(() -> {
48	                    ready.countDown();
49	                    start.await();
50	                    try {
51	                        facade.handlePumpCommand(new PumpCommandRequest(
52	                                "tc-" + idx, id, "PS-01", "START", T0, null));
53	                        accepted.incrementAndGet();
54	                    } catch (ApiException ex) {
55	                        // READ_COMMITTED 下先提交者对其余线程可见：表现为序列/站点冲突或泵已运行，均属唯一受理
56	                        if ("STATION_TIME_CONFLICT".equals(ex.getCode())
57	                                || "ZONE_SEQUENCE_CONFLICT".equals(ex.getCode())
58	                                || "PUMP_ALREADY_RUNNING".equals(ex.getCode())) {
59	                            conflict.incrementAndGet();
60	                        } else {
61	                            throw new RuntimeException(ex);
62	                        }
63	                    }
64	                    return null;
65	                });
66	            }
67	            assertThat(ready.await(5, TimeUnit.SECONDS)).isTrue();
68	            start.countDown();
69	            for (Future<?> f : futures) {
70	                f.get(10, TimeUnit.SECONDS);
71	            }
72	        } finally {
73	            pool.shutdownNow();
74	        }
75	
76	        assertThat(accepted.get()).isEqualTo(1);
77	        assertThat(conflict.get()).isEqualTo(threads - 1);
78	        // 唯一受理：仅一条启停任务、一条闸门记录；7 条冲突指令整事务回滚。
79	        // 幂等台账保留 2 条：1 条预警 + 1 条唯一受理的启泵指令。
