    void missingRequiredField_returns400() throws Exception {
        String bad = """
                {"requestId":"h-3","alertLevel":"ORANGE","alertTime":"2026-09-26T08:00:00"}
                """;
        mockMvc.perform(post("/api/warnings").contentType(MediaType.APPLICATION_JSON).content(bad))
