package com.example.starter.pump.domain;

import java.math.BigDecimal;
import java.time.LocalDateTime;

/**
 * 分区潮汐控制配置：顶托门槛与工况版本。未配置的分区不参与潮汐工况切换。
 *
 * @param zoneCode  流域分区代码
 * @param threshold 顶托门槛潮位（米，非负）：潮位>=门槛进入强排，恰等进入
 * @param mode      当前工况 NORMAL 常规 / FORCED 强排
 * @param version   工况版本：从1开始，每次成功变更（调门槛/工况切换）加1
 * @param updatedAt 最近变更时刻（Asia/Shanghai）
 */
public record TideControl(
        String zoneCode,
        BigDecimal threshold,
        String mode,
        int version,
        LocalDateTime updatedAt
) {

    /** 退出回差（米）：潮位回落到门槛减0.2米以下才退出强排，恰在回落线仍保持。 */
    public static final BigDecimal EXIT_HYSTERESIS = new BigDecimal("0.2");

    public boolean forced() {
        return "FORCED".equals(mode);
    }

    /** 退出线（米）：门槛减回差。 */
    public BigDecimal exitLine() {
        return threshold.subtract(EXIT_HYSTERESIS);
    }
}

package com.example.starter.pump.domain;

import java.math.BigDecimal;
import java.time.LocalDateTime;

/**
 * 分区潮位数据：按分区+UTC采集时刻唯一，非负。
 *
 * @param id          潮位数据ID
 * @param zoneCode    流域分区代码
 * @param readingTime 潮位采集时刻（UTC）
 * @param level       潮位（米），非负
 * @param late        是否迟到证据：true 只留证据不让工况倒退，false 正常参与判定
 * @param receivedAt  服务接收时刻（Asia/Shanghai）
 */
public record TideReading(
        Long id,
        String zoneCode,
        LocalDateTime readingTime,
        BigDecimal level,
        boolean late,
        LocalDateTime receivedAt
) {
}

package com.example.starter.pump.domain;

import java.math.BigDecimal;
import java.time.LocalDateTime;

/**
 * 工况切换候选序列：潮位越限生成，固定潮位版本与全部相关站闸门目标。
 *
 * @param id            切换候选ID
 * @param zoneCode      流域分区代码
 * @param direction     切换方向 ENTER_FORCED 进入强排 / EXIT_FORCED 退出强排
 * @param tideReadingId 触发潮位数据ID
 * @param tideTime      触发潮位时刻（UTC）
 * @param tideLevel     触发潮位（米）
 * @param pinnedVersion 生成时固定的分区工况版本
 * @param status        PENDING 待确认 / CONFIRMED 已确认 / SUPERSEDED 已被取代
 * @param createdAt     候选生成时刻（Asia/Shanghai）
 */
public record SwitchCandidate(
        Long id,
        String zoneCode,
        String direction,
        Long tideReadingId,
        LocalDateTime tideTime,
        BigDecimal tideLevel,
        int pinnedVersion,
        String status,
        LocalDateTime createdAt
) {

    public boolean pending() {
        return "PENDING".equals(status);
    }
}

package com.example.starter.pump.domain;

import java.math.BigDecimal;

/**
 * 候选固定的单站闸门目标。
 *
 * @param id            闸门目标ID
 * @param candidateId   所属切换候选ID
 * @param stationCode   泵站代码
 * @param targetOpening 目标闸门开度（百分比，0-100）
 */
public record GateTarget(
        Long id,
        Long candidateId,
        String stationCode,
        BigDecimal targetOpening
) {
}

package com.example.starter.pump.domain;

import java.math.BigDecimal;
import java.time.LocalDateTime;

/**
 * 闸门合成到位回执：按候选+站点唯一。
 *
 * @param id          回执ID
 * @param candidateId 所属切换候选ID
 * @param stationCode 泵站代码
 * @param opening     到位开度（百分比，0-100）
 * @param receivedAt  回执接收时刻（Asia/Shanghai）
 */
public record GateReceipt(
        Long id,
        Long candidateId,
        String stationCode,
        BigDecimal opening,
        LocalDateTime receivedAt
) {
}

