    public static final BigDecimal EXIT_HYSTERESIS = new BigDecimal("0.2");

    public boolean forced() {
        return "FORCED".equals(mode);
    }

    /** 退出线（米）：门槛减回差。 */
    public BigDecimal exitLine() {
        return threshold.subtract(EXIT_HYSTERESIS);
    }
}

