        assertThat(tideFacade.trajectory("ZN").currentMode()).isEqualTo("FORCED");
    }

    @Test
    void lateManualCommandAtOldTaskTime_conflicts_andNewTasksUntouched() {
        Long pumpdownId = setupControlAndPumpdown();
